const CURRENT_REALITY_PROMPT_LABELS=Object.freeze({ACTIVE_NOW:['What feels most active right now?','现在最活跃的是什么？'],HEAVY_NOW:['What currently feels heavy?','现在什么最让你觉得沉重？'],UNCERTAIN_NOW:['What feels uncertain?','什么让你觉得不确定？'],DECISION_STUCK:['Where are decisions stuck?','哪个决定卡住了？'],ENERGY_COST:['What is taking the most energy?','什么最消耗你的精力？'],SUPPORTIVE_NOW:['What feels supportive?','什么正在支持你？'],REPEATING_NOW:['What keeps repeating?','什么正在反复出现？'],UNDERSTAND_NOW:['What are you trying to understand?','你现在最想弄明白什么？']});
