const localizedPair=pair=>pair?.[locale()==='zh-Hans'?1:0]||pair?.[0]||'';

async function requestJson(url,options={}){const response=await fetch(url,{credentials:'same-origin',cache:'no-store',...options,headers:{accept:'application/json',...(options.headers||{})}});const payload=await response.json().catch(()=>({}));if(!response.ok||payload?.ok!==true){const error=new Error(payload?.error||'REQUEST_FAILED');error.code=payload?.error||'REQUEST_FAILED';error.payload=payload;throw error}return payload}
function selectedMethods(form){return [...form?.querySelectorAll('input[name="methods"]:checked')||[]].map(x=>x.value)}
function sharedTimingMethods(form,methods=selectedMethods(form)){const out=[...(Array.isArray(methods)?methods:[])];if(form?.elements?.externalProfileEnabled?.checked===true)out.push('humanDesign');return [...new Set(out)]}
function requirementsFor(methods){const rules=methods.map(x=>METHOD_REQUIREMENTS[x]).filter(Boolean);return Object.freeze({date:rules.some(x=>x.date===true),timeRequired:rules.some(x=>x.time===true),timeUseful:rules.some(x=>x.time===true||x.time==='optional'),place:rules.some(x=>x.place===true),traditionalSex:methods.includes('bazi')||methods.includes('ziwei')})}
function methodStateCard(m,state='ready'){const msg=m.message?`<p class="cx-meta">${esc(m.message)}</p>`:'';return `<article class="cx-personal-result-method"><div class="cx-personal-result-method__head"><div><h3 class="cx-heading">${esc(m.label||m.publicMethodCode||tr('Perspective','视角'))}</h3>${msg}</div><span class="cx-personal-status-chip" data-state="${state}">${esc(state==='ready'?tr('Ready','已准备'):tr('Needs attention','需要补充'))}</span></div></article>`}
function methodLabel(result){const labels=METHOD_LABELS[result?.methodId];return result?.methodLabel||(labels?(locale()==='zh-Hans'?labels.zh:labels.en):tr('Perspective','视角'))}
function readingMethods(){return arr(view?.reading?.methods)}
function acceptedResults(){return readingMethods().filter(result=>result?.state==='READY_TO_READ')}
function limitedResults(){return readingMethods().filter(result=>result?.state!=='READY_TO_READ')}
function methodNativeProducts(){return Object.values(view?.methodNativeReading||{}).filter(x=>x?.publicationDecision?.customerPublishable===true)}
function nativeProduct(methodId){return methodNativeProducts().find(x=>x?.methodId===methodId)||null}

function renderReadingMap(){
  const node=document.querySelector('[data-cx-reading-map]');if(!node)return;
  const rows=arr(view?.reading?.map);
  const icon={PREPARED:'CXICON-STATUS-AVAILABLE',READABLE:'CXICON-STATUS-AVAILABLE',NEEDS_INFORMATION:'CXICON-STATUS-UNAVAILABLE',WAITING_FOR_CONFIRMATION:'CXICON-STATUS-PARTIAL',NOT_STARTED:'CXICON-STATUS-SEPARATE'};
  const stateLabel={PREPARED:tr('Prepared','已准备'),READABLE:tr('Ready to read','可以阅读'),NEEDS_INFORMATION:tr('Needs more information','还需要资料'),WAITING_FOR_CONFIRMATION:tr('Waiting for you','等待你确认'),NOT_STARTED:tr('Not started','尚未进行')};
  node.innerHTML=`<div class="cx-reading-map-live" aria-label="${esc(tr('Six-stage reading map','六阶段读取地图'))}">${rows.map((r,i)=>`<article data-state="${r.state}"><div class="cx-reading-map-live__index">${String(i+1).padStart(2,'0')}</div><img data-cx-asset="${icon[r.state]||icon.NOT_STARTED}" alt=""><div><strong>${esc(r.label)}</strong><span>${esc(r.detail)}</span></div><em>${esc(stateLabel[r.state]||tr('Still open','仍未确定'))}</em></article>`).join('')}</div>`;
  void hydrateCustomerAssets(node);
}
function renderPersonalMap(){const node=document.querySelector('[data-cx-personal-map]');if(!node)return;const ready=acceptedResults().map(x=>({label:methodLabel(x),state:'ready'})),blocked=limitedResults().map(x=>({label:methodLabel(x),state:'needs'})),items=[...ready,...blocked];if(!items.length){node.innerHTML=empty(tr('No perspective is ready to map yet.','目前还没有可放进阅读地图的视角。'));return}node.innerHTML=`<div class="cx-personal-map" role="img" aria-label="${esc(tr('Personal Reality perspective map','Personal Reality 视角地图'))}"><div class="cx-personal-map__center"><span>${esc(tr('YOUR REALITY','你的现实'))}</span><strong>${esc(tr('One life','同一个人'))}</strong></div>${items.map((m,i)=>`<div class="cx-personal-map__node" data-index="${i}" data-state="${m.state}"><strong>${esc(m.label||tr('Perspective','视角'))}</strong><small>${esc(m.state==='ready'?tr('Ready to read','可以阅读'):tr('Needs more information','还需要资料'))}</small></div>`).join('')}</div><p class="cx-meta cx-personal-map__note">${esc(tr('The lines show that these perspectives belong to the same reading. They do not mean the methods agree with one another.','这些连线只表示不同视角被放在同一次阅读里，并不表示它们彼此同意。'))}</p>`}
function interpretationBlock(method){const methodId=method.methodId||METHOD_ID_BY_PUBLIC[method.publicMethodCode];const match=readingMethods().find(x=>x.methodId===methodId);const items=arr(match?.insights);if(items.length)return `<section class="cx-personal-meaning"><p class="cx-eyebrow">${esc(tr('REVIEWED INTERPRETATION','经过审核的解释'))}</p>${items.slice(0,5).map(item=>`<article><h4>${esc(item.title)}</h4><p>${esc(item.plainLanguageExplanation)}</p></article>`).join('')}</section>`;return `<section class="cx-personal-meaning cx-personal-meaning--open"><p class="cx-eyebrow">${esc(tr('WHAT REMAINS OPEN','仍然未确定'))}</p><p>${esc(tr('A calculated structure was returned, but the governed customer layer did not supply a complete explanation this time. The structure remains visible without inventing a meaning.','这次已经返回计算结构，但受治理的客户层没有提供完整解释。页面会保留结构，同时不会自行补写意义。'))}</p></section>`}
function customerStateLabel(state){const key=String(state||'NOT_STARTED');const labels={READY_TO_READ:tr('Ready to read','可以阅读'),PARTIALLY_PREPARED:tr('Some readings are ready','部分内容可以阅读'),NEEDS_ATTENTION:tr('Needs more information','还需要更多资料'),PREPARED:tr('Prepared','已准备'),READABLE:tr('Ready to read','可以阅读'),NEEDS_INFORMATION:tr('Needs more information','还需要资料'),WAITING_FOR_CONFIRMATION:tr('Waiting for you','等待你确认'),NOT_STARTED:tr('Not started','尚未进行')};return labels[key]||tr('Still open','仍未确定')}
function graphBoundaryBlock(result){const technical=result?.technical||{},digest=String(technical.projectionDigest||''),lifecycle=result?.state||'NOT_STARTED';return `<aside class="cx-graph-boundary" data-method="${esc(result?.methodId||'')}"><div><strong>${esc(tr('WHAT THIS GRAPH SHOWS','这张图显示什么'))}</strong><span>${esc(tr('Calculated relationships from the same governed projection used by this reviewed reading.','来自本次经过审核的阅读所使用的同一份受治理计算结果。'))}</span></div><div><strong>${esc(tr('WHAT IT DOES NOT ESTABLISH','它不能证明什么'))}</strong><span>${esc(tr('The graph does not create meaning, lived-reality evidence or a decision about you.','结构图不会自行创造意义、现实经历证据或关于你的决定。'))}</span></div><details><summary>${esc(tr('How this result was prepared','这项结果怎样形成'))}</summary><dl><dt>${esc(tr('Perspective','视角'))}</dt><dd>${esc(methodLabel(result))}</dd><dt>${esc(tr('Reading availability','阅读状态'))}</dt><dd>${esc(customerStateLabel(lifecycle))}</dd><dt>${esc(tr('Result fingerprint','结果指纹'))}</dt><dd>${esc(digest||tr('Not exposed','未提供'))}</dd>${technical.houseSystemId?`<dt>${esc(tr('House-system code','宫制代码'))}</dt><dd>${esc(technical.houseSystemId)}</dd>`:''}</dl></details></aside>`}
function structureBoundaryBlock(method){return `<section class="cx-personal-structure-boundary"><p class="cx-eyebrow">${esc(tr('WHAT REMAINS OPEN','仍然未确定'))}</p><p>${esc(tr('Calculated structure can be inspected without being promoted to a fact about lived Reality. Interpretation appears only when the governed customer layer supplied it.','计算结构可以被检查，但不会因此升级为现实事实；只有受治理的客户解释层真正提供了解释时，解释才会出现。'))}</p></section>`}
function renderCrossPerspectiveComparison(){const node=document.querySelector('[data-cx-pattern-comparison]');if(!node)return;const results=acceptedResults().filter(x=>arr(x.insights).length);const allMethods=new Set(results.map(x=>x.methodId));if(results.length<2||!['AST','BZR','NUM','ZWR'].some(id=>allMethods.has(id))){node.innerHTML=`<div class="cx-p1-empty">${esc(tr('Cross-perspective comparison opens only when Astrology, BaZi, Numerology and Zi Wei each have an accepted reading in the same result. Until then, every available perspective remains readable on its own.','只有占星、八字、数字学与紫微斗数在同一次结果中都形成已获接受的阅读后，跨视角比较才会开启。在此之前，每个已准备好的视角仍可独立阅读。'))}</div>`;return}node.innerHTML=`<section class="cx-cross-perspective-compare"><header><p class="cx-eyebrow">${esc(tr('FOUR PERSPECTIVES, KEPT DISTINCT','四种视角，彼此保持独立'))}</p><p>${esc(tr('The reviewed themes are shown side by side while remaining attached to the perspective that produced them. No automatic personality conclusion or consensus score is created.','经过审核的主题可以并列查看，但仍归属于产生它们的视角；系统不会自动生成统一人格结论或“共识分数”。'))}</p></header><div>${results.map(result=>`<article><strong>${esc(methodLabel(result))}</strong>${arr(result.insights).slice(0,4).map(item=>`<span>${esc(item.title)}</span>`).join('')}</article>`).join('')}</div></section>`}
function renderSourcesAndBoundaries(){const node=document.querySelector('[data-cx-personal-sources]');if(!node)return;const results=readingMethods();if(!results.length){node.innerHTML=empty(tr('No governed result source is available to inspect yet.','目前还没有可检查的受治理结果来源。'));return}node.innerHTML=`<div class="cx-source-boundary-list">${results.map(result=>{const technical=result.technical||{},digest=String(technical.projectionDigest||''),boundary=technical.boundary||{},lifecycle=result.state||'NOT_STARTED';return `<article><header><div><span class="cx-meta">${esc(tr('Perspective reading','视角阅读'))}</span><h3>${esc(methodLabel(result))}</h3></div><span class="cx-personal-status-chip" data-state="${esc(String(result.state||'open').toLowerCase())}">${esc(customerStateLabel(lifecycle))}</span></header><p class="cx-source-boundary-summary">${esc(result.summary||tr('This result remains within its own method and evidence boundary.','这项结果继续保留在本方法与证据边界内。'))}</p><details><summary>${esc(tr('Technical Details','技术详情'))}</summary><dl><dt>${esc(tr('Internal method code','内部方法代码'))}</dt><dd>${esc(technical.methodId||result.methodId||'')}</dd><dt>${esc(tr('Projection reference','投影参考'))}</dt><dd>${esc(technical.projectionId||'')}</dd><dt>${esc(tr('Result fingerprint','结果指纹'))}</dt><dd class="cx-source-digest">${esc(digest||tr('Not exposed','未提供'))}</dd><dt>${esc(tr('Lifecycle record','生命周期记录'))}</dt><dd>${esc(JSON.stringify(technical.lifecycle||{}))}</dd>${technical.houseSystemId?`<dt>${esc(tr('House-system code','宫制代码'))}</dt><dd>${esc(technical.houseSystemId)}</dd>`:''}<dt>${esc(tr('Does the display invent meaning?','页面会自行创造意义吗？'))}</dt><dd>${esc(boundary.rendererCreatesMeaning===false?tr('No','不会'):tr('Not established','未确定'))}</dd><dt>${esc(tr('Does this establish a lived-reality fact?','这会建立现实经历事实吗？'))}</dt><dd>${esc(boundary.realityKnown===false?tr('No','不会'):tr('Not established','未确定'))}</dd></dl></details></article>`}).join('')}</div>`}


function wheelPoint(longitude,radius=42){const a=((Number(longitude)||0)-90)*Math.PI/180;return {x:50+Math.cos(a)*radius,y:50+Math.sin(a)*radius}}
function astroDegreeMinute(value){const n=Number(value);if(!Number.isFinite(n))return '';const degree=Math.floor(n),minute=Math.round((n-degree)*60);return `${degree}° ${String(minute===60?0:minute).padStart(2,'0')}′`}
function renderAstrologyWheel(ast){const bodies=arr(ast?.visualModel?.bodies),angles=arr(ast?.visualModel?.angles),aspects=arr(ast?.visualModel?.aspects),houses=arr(ast?.visualModel?.houses);if(!bodies.length)return '';const points=new Map(bodies.map(b=>[b.code,wheelPoint(b.longitude,37)]));const lines=aspects.map(a=>{const p1=points.get(a.fromCode),p2=points.get(a.toCode);return p1&&p2?`<line x1="${p1.x}" y1="${p1.y}" x2="${p2.x}" y2="${p2.y}" data-aspect="${esc(a.type||'')}"/>`:''}).join('');const radial=[...Array(12)].map((_,i)=>{const a=wheelPoint(i*30,45),b=wheelPoint(i*30,31);return `<line class="cx-ast-wheel__sector" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/>`}).join('');const houseRadial=houses.map(h=>{const a=wheelPoint(h.longitude,45),b=wheelPoint(h.longitude,7);return `<line class="cx-ast-wheel__house" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/>`}).join('');const bodyNodes=bodies.map(b=>{const p=points.get(b.code);return `<g class="cx-ast-wheel__body" transform="translate(${p.x} ${p.y})" tabindex="0" role="listitem" aria-label="${esc(`${b.label} ${astroDegreeMinute(b.longitude)}`)}"><circle r="2.7"/><text y="-4">${esc(b.label)}</text></g>`}).join('');const angleNodes=angles.map(a=>{const p=wheelPoint(a.longitude,46);return `<g class="cx-ast-wheel__angle" transform="translate(${p.x} ${p.y})"><circle r="1.7"/><text y="-3">${esc(a.label)}</text></g>`}).join('');return `<figure class="cx-ast-wheel"><svg viewBox="0 0 100 100" role="img" aria-labelledby="cx-ast-wheel-title cx-ast-wheel-desc"><title id="cx-ast-wheel-title">${esc(tr('Astrology birth structure map','占星出生结构图'))}</title><desc id="cx-ast-wheel-desc">${esc(tr('Calculated positions, actual house cusps, angles and major aspects from one projection.','同一投射中的星体位置、实际宫头、四轴与主要相位。'))}</desc><circle class="cx-ast-wheel__outer" cx="50" cy="50" r="45"/><circle class="cx-ast-wheel__inner" cx="50" cy="50" r="31"/>${radial}${houseRadial}<g class="cx-ast-wheel__aspects">${lines}</g><g role="list">${bodyNodes}</g>${angleNodes}<circle class="cx-ast-wheel__center" cx="50" cy="50" r="7"/><text class="cx-ast-wheel__center-label" x="50" y="49">${esc(tr('BIRTH','出生'))}</text><text class="cx-ast-wheel__center-label" x="50" y="53">${esc(tr('STRUCTURE','结构'))}</text></svg><figcaption>${esc(tr('A visual map of the calculated positions, actual house cusps, angles and major aspects in this reading.','这张图把本次实际计算出的星体位置、实际宫头、四轴与主要相位放在同一张结构图里。'))}</figcaption></figure>`}
function renderAstrology(ast){if(!ast)return '';const positions=arr(ast.bodies).map(b=>`<article class="cx-ast-placement"><header><strong>${esc(b.label)}</strong>${b.retrograde===true?`<span>${esc(tr('Retrograde','逆行'))}</span>`:''}</header><div><b>${esc(b.signLabel||'')}</b><span>${b.degreeInSign==null?'':esc(astroDegreeMinute(b.degreeInSign))}${b.houseNumber?` · ${esc(tr(`House ${b.houseNumber}`,`第 ${b.houseNumber} 宫`))}`:''}</span></div></article>`).join('');const aspects=arr(ast.aspects).slice(0,16).map(x=>`<li><span>${esc(x.fromLabel)} · ${esc(x.toLabel)}</span><strong>${esc(x.typeLabel)}</strong>${x.relationMeaning?.definition?`<small>${esc(x.relationMeaning.definition)}</small>`:''}</li>`).join('');return `<article class="cx-card cx-astrology-reading"><header class="cx-astrology-reading__head"><div><p class="cx-eyebrow">${esc(tr('ASTROLOGY CALCULATED STRUCTURE','占星计算结构'))}</p><h3>${esc(tr('Your birth sky as one connected structure','把出生时的天空，看成一张彼此连接的结构图'))}</h3><p class="cx-meta cx-astrology-method">${esc(tr('Calculation method','计算方式'))}: ${esc(ast.houseSystem?.label||tr('Recorded house system','已记录宫制'))}</p></div><span class="cx-personal-status-chip" data-state="ready">${esc(ast.executionCompleteness==='COMPLETE'?tr('Structure established','结构已建立'):tr('Some structure established','部分结构已建立'))}</span></header><div class="cx-astrology-reading__visual">${renderAstrologyWheel(ast)}<div class="cx-astrology-reading__intro"><h4>${esc(tr('How to read this','怎样开始阅读'))}</h4><p>${esc(tr('This section shows the calculated structure only. The reviewed interpretation appears separately below and remains bound to the accepted customer reading.','这一部分只显示计算结构；经过审核的解释会在下方独立呈现，并继续绑定到已经获接受的客户阅读。'))}</p></div></div><section><h4>${esc(tr('Core placements','核心位置'))}</h4><div class="cx-ast-placement-grid">${positions}</div></section>${aspects?`<section class="cx-ast-aspect-list"><h4>${esc(tr('Major structural relationships','主要结构关系'))}</h4><ul>${aspects}</ul></section>`:''}${interpretationBlock({publicMethodCode:'ASTROLOGY_PROJECTION'})}</article>`}

function renderOverview(){const node=document.querySelector('[data-cx-personal-overview]'),ready=acceptedResults(),limited=limitedResults(),bazi=nativeProduct('BZR');const nativeHighlights=bazi?arr(bazi.summary?.keyPoints).slice(0,5).map(text=>({label:tr('BaZi','八字'),title:tr('Key chart structure','命局重点'),text})):[];const genericHighlights=ready.filter(result=>!(bazi&&result.methodId==='BZR')).flatMap(result=>arr(result.insights).slice(0,3).map(item=>({label:methodLabel(result),title:item.title,text:item.plainLanguageExplanation})));const highlights=[...nativeHighlights,...genericHighlights].slice(0,5);node.innerHTML=`<section class="cx-personal-overview-lead"><p class="cx-eyebrow">${esc(tr('YOUR READING, IN PLAIN LANGUAGE','用容易理解的方式开始阅读'))}</p><h3>${esc(ready.length?tr(`${ready.length} perspective${ready.length===1?' is':'s are'} ready to read.`,`${ready.length} 个视角已经可以阅读。`):tr('This reading still needs more information.','这次阅读仍需要更多资料。'))}</h3><p>${esc(tr('Method-native Full Production results lead where they are available; every highlight remains attached to its own perspective.','已有方法原生 Full Production 的视角会优先呈现；每项重点仍归属于产生它的方法。'))}</p></section>${highlights.length?`<div class="cx-personal-overview-highlights">${highlights.map(item=>`<article><span>${esc(item.label)}</span><h4>${esc(item.title)}</h4><p>${esc(item.text)}</p></article>`).join('')}</div>`:''}<div>${ready.map(result=>methodStateCard({label:methodLabel(result),message:result.summary},'ready')).join('')}${limited.map(result=>methodStateCard({label:methodLabel(result),message:arr(result.openQuestions)[0]||result.stateLabel},'needs-info')).join('')}</div>`;document.querySelector('[data-cx-personal-handoff]').disabled=!ready.length}
